query:
# ArcSight / EDR hunting variant — iterate over host telemetry
$pattern = 'Invoke-WebRequest|Invoke-RestMethod|Net\.WebClient|DownloadFile|DownloadString|Start-BitsTransfer'
$since = (Get-Date).AddDays(-7)

Get-WinEvent -FilterHashtable @{ LogName = 'Microsoft-Windows-PowerShell/Operational'; StartTime = $since } |
  Where-Object { $_.Message -match $pattern } |
  ForEach-Object {
    [pscustomobject]@{
      Time     = $_.TimeCreated
      Host     = $_.MachineName
      Rule     = $_.Id
      Evidence = ($_.Message -split "`n")[0..3] -join ' '
    }
  } | Sort-Object Time -Descending | Format-Table -AutoSize
